package com.johnny.hotel.settlement;import com.johnny.hotel.ar.ArAccess;import com.johnny.hotel.businessdate.BusinessDateService;import com.johnny.hotel.entity.SysAuditLog;import com.johnny.hotel.exception.BusinessException;import com.johnny.hotel.mapper.SysAuditLogMapper;import com.johnny.hotel.pagination.*;import com.johnny.hotel.payment.*;import com.johnny.hotel.settlement.SettlementRequests.*;import lombok.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.*;import java.time.*;import java.util.*;
@Service@RequiredArgsConstructor public class SettlementService{private final SettlementMapper db;private final ArAccess access;private final BusinessDateService dates;private final PaymentCoreMapper transactions;private final SysAuditLogMapper audits;private final PaginationSupport pages;private final Clock clock;
 private void req(boolean b,String m){if(!b)throw new BusinessException(m);}private void one(int n){if(n!=1)throw new BusinessException(409,"Settlement state changed");}private String norm(String s){return s==null?null:s.trim().toUpperCase(Locale.ROOT);}private BigDecimal money(BigDecimal x){req(x!=null&&x.scale()<=2,"Invalid settlement money scale");return x.setScale(2);}
 @Transactional public SettlementView importBatch(Import r){var actor=access.actor();String provider=norm(r.provider),currency=norm(r.currency);req(r.periodStart==null||r.periodEnd==null||!r.periodStart.isAfter(r.periodEnd),"Invalid settlement period");var seed=SettlementBatch.builder().provider(provider).providerBatchId(r.providerBatchId.trim()).currency(currency).periodStart(r.periodStart).periodEnd(r.periodEnd).declaredGross(money(r.grossAmount)).declaredFee(money(r.feeAmount)).declaredNet(money(r.netAmount)).postingBusinessDate(dates.postingDate()).providerCreatedAt(r.providerCreatedAt).providerSettledAt(r.providerSettledAt).importedBy(actor.id()).build();db.ensureBatch(seed);var batch=db.lockBatch(provider,seed.getProviderBatchId());req(batch!=null,"Settlement batch lock failed");if(!"PROCESSING".equals(batch.getStatus())){same(batch,seed);return view(batch.getId());}
  BigDecimal gross=BigDecimal.ZERO,fee=BigDecimal.ZERO,net=BigDecimal.ZERO;String problem=null;List<SettlementItem> rows=new ArrayList<>();for(Item x:r.items){String st=norm(x.sourceType),dir=norm(x.direction);var source=db.moneySource(st,x.sourceId);String issue=null;if(db.itemBySource(st,x.sourceId)!=null)issue="Source event was already settled";else if(source==null)issue="Source money event is missing";else if(!Objects.equals(source.getProviderTransactionId(),x.providerPaymentId))issue="Provider reference mismatch";else if(!provider.equals(norm(source.getProvider())))issue="Provider mismatch";else if(!currency.equals(norm(x.currency))||!currency.equals(norm(source.getCurrency())))issue="Currency mismatch";else if(source.getAmount().compareTo(x.grossAmount)!=0)issue="Gross amount mismatch";else if(("IN".equals(dir)&&!"EXTERNAL_IN".equals(source.getDirection()))||("OUT".equals(dir)&&!"EXTERNAL_OUT".equals(source.getDirection())))issue="Direction mismatch";BigDecimal g=money(x.grossAmount),f=money(x.feeAmount),n=money(x.netAmount);if(("IN".equals(dir)&&g.subtract(f).compareTo(n)!=0)||("OUT".equals(dir)&&g.add(f).compareTo(n)!=0))issue=issue==null?"Item net amount mismatch":issue;gross=gross.add("IN".equals(dir)?g:g.negate());fee=fee.add(f);net=net.add("IN".equals(dir)?n:n.negate());if(issue!=null&&problem==null)problem=issue;rows.add(SettlementItem.builder().batchId(batch.getId()).sourceType(st).sourceId(x.sourceId).providerPaymentId(x.providerPaymentId).direction(dir).grossAmount(g).feeAmount(f).netAmount(n).currency(norm(x.currency)).status(issue==null?"MATCHED":source==null?"MISSING":"MISMATCH").exceptionReason(issue).providerOccurredAt(x.providerOccurredAt).build());}
  if(gross.compareTo(seed.getDeclaredGross())!=0||fee.compareTo(seed.getDeclaredFee())!=0||net.compareTo(seed.getDeclaredNet())!=0)problem=problem==null?"Batch totals mismatch":problem;for(var row:rows){if(db.itemBySource(row.getSourceType(),row.getSourceId())==null)one(db.insertItem(row));}String rec=problem==null?"MATCHED":rows.stream().anyMatch(i->"MISSING".equals(i.getStatus()))?"MISSING":"MISMATCH";one(db.reconcile(batch.getId(),gross,fee,net,problem==null?"SETTLED":"EXCEPTION",rec,problem));audit(actor.id(),"IMPORT_GATEWAY_SETTLEMENT",batch.getId());return view(batch.getId());}
 @Transactional public GatewayPayout payout(Long batchId,Payout r){var actor=access.actor();var snapshot=db.batch(batchId);req(snapshot!=null,"Settlement batch not found");var batch=db.lockBatch(snapshot.getProvider(),snapshot.getProviderBatchId());req(batch!=null,"Settlement batch lock failed");var old=db.payoutByBatch(batchId);if(old!=null){req(old.getProviderPayoutId().equals(r.providerPayoutId)&&old.getAmount().compareTo(r.amount)==0,"Payout request conflicts with existing payout");return old;}String cur=norm(r.currency);BigDecimal amount=money(r.amount);String issue=null;if(!batch.getCurrency().equals(cur))issue="Payout currency mismatch";else if(batch.getDeclaredNet().compareTo(amount)!=0)issue="Payout amount mismatch";var p=GatewayPayout.builder().batchId(batchId).provider(batch.getProvider()).providerPayoutId(r.providerPayoutId.trim()).currency(cur).amount(amount).status("COMPLETED").reconciliationStatus(issue==null?"MATCHED":"MISMATCH").exceptionReason(issue).expectedAt(r.expectedAt).paidAt(r.paidAt).bankReference(r.bankReference).postingBusinessDate(dates.postingDate()).confirmedBy(actor.id()).build();db.ensurePayout(p);var locked=db.lockPayout(batch.getProvider(),p.getProviderPayoutId());req(locked!=null,"Payout lock failed");if(!Objects.equals(locked.getId(),p.getId())&&p.getId()!=null){req(locked.getBatchId().equals(batchId)&&locked.getAmount().compareTo(amount)==0,"Provider payout id conflict");return locked;}one(transactions.insertTransaction(HotelTransactionRecord.builder().direction("INTERNAL_TRANSFER").amount(amount).currency(cur).sourceType("PROCESSOR_PAYOUT").sourceId(locked.getId()).businessReferenceType("SETTLEMENT_BATCH").businessReferenceId(batchId).paymentMethod("BANK_TRANSFER").channel("PROCESSOR_SETTLEMENT").provider(batch.getProvider()).providerTransactionId(p.getProviderPayoutId()).initiatorType("SYSTEM").operatorUserId(actor.id()).description("Processor payout to hotel bank").occurredAt(r.paidAt).businessDate(p.getPostingBusinessDate()).build()));audit(actor.id(),"CONFIRM_GATEWAY_PAYOUT",locked.getId());return locked;}
 @Transactional(readOnly=true)public SettlementView get(Long id){access.actor();req(db.batch(id)!=null,"Settlement batch not found");return view(id);}@Transactional(readOnly=true)public PageResult<SettlementBatch> list(Integer page,Integer size){access.actor();var w=pages.window(page,size,true);return pages.result(w,db.batches(w.offset(),pages.limit(w)),db.batchCount());}@Transactional(readOnly=true)public SettlementMetrics metrics(){access.actor();return db.metrics();}
 private SettlementView view(Long id){return SettlementView.builder().batch(db.batch(id)).items(db.items(id)).payout(db.payoutByBatch(id)).build();}private void same(SettlementBatch a,SettlementBatch b){req(a.getCurrency().equals(b.getCurrency())&&a.getDeclaredGross().compareTo(b.getDeclaredGross())==0&&a.getDeclaredFee().compareTo(b.getDeclaredFee())==0&&a.getDeclaredNet().compareTo(b.getDeclaredNet())==0,"Provider batch id conflicts with different settlement");}private void audit(Long actor,String action,Long id){one(audits.insert(SysAuditLog.builder().operatorId(actor).action(action).detail("Settlement "+id).build()));}
}
